module parity_8bit (
    input [7:0] in,
    output out
);
    wire sum1, sum2, sum3, sum4;

    // XOR operations for the even positions (0, 2, 4, 6)
    xor u21 ( .S(sum0), A(in[0]), B(in[2]) );
    xor u22 ( .S(sum1), A(in[2]), B(in[4]) );
    xor u23 ( .S(sum2), A(in[4]), B(in[6]) );
    // XOR operations for the odd positions (1, 3, 5, 7)
    xor u11 ( .S(sum3), A(in[1]), B(in[3]) );
    xor u12 ( .S(sum4), A(in[3]), B(in[5]) );

    // OR to sum up sum1 and sum2
    or u41 ( .S(sum3), A(sum1), B(sum2) );
    or u42 ( .S(sum4), A(sum3), B(sum4) );

    // Final XOR for output
    xor u24 ( .S(out), A(sum4), B(sum4) );    

endmodule

