module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output out
);

  inout bits [31:0] b1,b2,b3,b4;
  wire sel0,sel1,sel2,sel3;

  reg sel0,sel1,sel2,sel3;

  assign sel0 = (~sel[1] & sel[0]);
  assign sel3 = (sel[1] & ~sel[0]);
  assign sel1 = (sel[1] & sel[0]);
  assign sel2 = (~sel[1] & sel[0]);

  // b1 sel0
  always @(sel0 or in[0])
    if (sel0) b1 = in[0];

  // b2 sel1
  always @(sel1 or in[1])
    if (sel1) b2 = in[1];

  // b3 sel2
  always @(sel2 or in[2])
    if (sel2) b3 = in[2];

  // b4 sel3
  always @(sel3 or in[3])
    if (sel3) b4 = in[3];

  assign out = b1 | b2 | b3 | b4;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire w1;
    wire w2;
    wire w3;
    wire w4;
    wire w5;
    wire w6;
    wire w7;
    wire w8;

    assign w1 = in[0];
    assign w2 = in[1];
    assign w3 = in[2];
    assign w4 = in[3];

    // Multiplexer logic
    assign out = (sel[1] & sel[0]) ? w3 : ((~sel[1]) & sel[0]) ? w2 : ((~sel[1]) & (~sel[0])) ? w1 : w4;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire w1, w2, w3, w4, w5, w6, w7, w8;

    // First level 2x2 muxes
    assign w1 = (sel[1]) | (sel[0] & (~in[0])[0]);
    assign w2 = (~sel[1]) & in[0];
    assign w3 = (~sel[1]) & in[1];
    assign w4 = sel[1] & in[2];

    // Second level muxes
    assign w5 = (~sel[0]) & w1;
    assign w6 =  sel[0]  & w2;

    wire w7_1, w8_1, w7_2, w8_2;
    wire w7_3, w7_4, w8_3, w8_4;

    assign w7_1 = (~sel[1]) & w3;
    assign w7_2 =  sel[1] & w4;
    assign w7_3 = (~sel[0]) & w7_1;
    assign w7_4 =  sel[0]  & w7_2;
    assign w8_1 = (~sel[1]) & w5;
    assign w8_2 =  sel[1] & w6;
    assign w8_3 = (~sel[0]) & w8_1;
    assign w8_4 =  sel[0]  & w8_2;

    assign out = (~w7_3) & (~w8_4); // Final output

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
wire w0, w1, w2, w3, w4, w5, w6, w7, w8;

assign w0 = ~in[0];
assign w1 = in[0];
assign w2 = ~in[1];
assign w3 = in[1];
assign w4 = ~in[2];
assign w5 = in[2];
assign w6 = ~in[3];
assign w7 = in[3];

assign w8 = ((sel == 2'd0) ? w4 : ((sel == 2'd1) ? w5 : ((sel == 2'd2) ? w6 : w7)));

assign out = (sel == 2'd0) ? w0 : ((sel == 2'd1) ? w1 : ((sel == 2'd2) ? w2 : w3));

endmodule

