module majority (
    input a, b, c,
    output out
);

wire out_c, ANDb, ANDc, ANDd, ANDe, ANDf, ANDg, ANDh;

// First stage: A AND c
assign &ANDc = {c, a & c};

// Second stage  : B AND c
assign &ANDb = {b, c & b};

// Third stage : C AND (A AND B) - This includes both (A&c)&(C&b) and (A&b)&(C&c) terms, ensuring we cover all combinations
assign &ANDc = c & ({&ANDc, &ANDd});

// Fourth stage : (A AND c) OR (B AND c)
assign &ANDb = (&ANDc | &ANDb);

// Fifth stage : (A AND b) OR (B AND a)
assign &ANDb = (&ANDb | (&b & &ANDb));

// Final stage: Combine all output bits
assign out = &ANDb;

endmodule

module majority (
    input a, b, c,
    output out
);

    wire x1, x2, x3, x4;

    // Implementing the first level of AND-gates
    x1 = b && c;
    x2 = a && b;
    x3 = a && c;
    x4 = b && x2;

    // Implementing the second level of AND-gates
    x1 = x2 && x3;

    // Implementing the final AND-gate for the output
    out = c && (x1 || x3);

endmodule

