module eq_comparator (
	 input [3:0] a,
	input [3:0] b,
 output equal
);
	 wire y1, y2, y3, y4, y5, y6;
	// XOR gates and subsequent logic
	assign y1 = ~((b[0]^b[1])|(a[0]^a[1]));
	assign y2 = ~(b[1]^a[1]);
	assign y3 = ~(b[0]^a[0])|(y2);
	assign y4 = y1&y3;
	assign y5 = (~a[0]|~a[1])&(b[0]|b[1]);
	assign y6 = (a[0]^a[1])^(b[0]^b[1]);
	// Final output
	assign equal = ~(y4|y5|y6);
endmodule

