module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire x0, x1, x2, x3;      // Outputs from first comparator layer
    wire y0, y1, y2, y3;      // Outputs from second comparator layer

    // First layer of comparators
    x0 = ~(a[0] ^ b[0]);
    x1 = ~(a[1] ^ b[1]);
    x2 = ~(a[2] ^ b[2]);
    x3 = ~(a[3] ^ b[3]);

    // Second layer of comparators
    y0 = ~(x0 ^ x1);
    y1 = ~(x2 ^ x3);
    y2 = ~(y0 ^ y1);
    y3 = ~(x0 ^ x1); // This line is redundant but follows the diagram structure

    // Equal output
    assign equal = ~(y2 ^ y3);

endmodule

module eq_comparator(
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire sum_a_0, sum_a_1, sum_a_2, sum_a_3;
    wire sum_b_0, sum_b_1, sum_b_2, sum_b_3;
    wire xor_out_0, xor_out_1, xor_out_2, xor_out_3;
    wire final_xor;
    wire carry_out_a, carry_out_b;
    wire final_and;

    // XOR Gates
    xor_xor #(); always @(*) xor_out_0 = a[0]^b[0];
    xor_xor #(); always @(*) xor_out_1 = a[1]^b[1];
    xor_xor #(); always @(*) xor_out_2 = a[2]^b[2];
    xor_xor #(); always @(*) xor_out_3 = a[3]^b[3];

    // AND Gate
    and_and #(); always @(*) final_and = xor_out_0 & xor_out_1;

    // Output assignment
    assign equal = xor_out_0 & xor_out_1 & xor_out_2 & xor_out_3 & final_and;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    // Define internal signals
    wire s0, s1, s2, s3;

    // Logic for each output bit
    assign s0 = (~&c) AND (~in[1]) AND (~in[0]);
    assign s1 = (~&c) AND (&c) AND (~in[1]);
    assign s2 = (~&c) AND (&c) AND (in[0]);
    assign s3 = (~&c) AND (in[1]);

    // Connect inputs to the logic gates
    wire(&c ^ ~in[0] ^ ~in[1] & (~s0 == 1 & (~s1 == 1 & ~s2 == 1 & ~s3 == 1)))

endmodule

module decoder_2to4 (
