);

    assign out[0] = ~(in[1] ^ in[0]);
    assign out[1] = ~in[1] & in[0];
    assign out[2] = in[1] & ~in[0];
    assign out[3] = in[1] & in[0];

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out[2 * in + 1] = ~(in[0] & in[1]);
assign out[2 * in + 2] = ~(~in[0] & in[1]);
assign out[2 * in + 3] = (~in[0] & ~in[1]);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    bit in1, in2;
    bit out1, out2, out3, out4;
    logic gate U1, U2, U3, U4;

assign U1 = in1 & ~in2;   // out[0]
assign U2 = ~in1 & in2;   // out[1]
assign U3 = in1 & in2 & (~in1 | in2);  // out[2]
assign U4 = ~in1 & in2 & (in1 | in2);  // out[3]

endmodule

