module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
wire w_2;
wire w_3;
wire w_1;
assign w_2 = in[2];
assign w_3 = in[3];
assign w_1 = in[1];

assign code[0] = (w_2 & ~w_1) & (!w_3 | w_2);
assign code[1] = (w_1 & w_2) & (!w_3);

