module priority_encoder (
    output reg [2:0] in,
    input [2:0] out,
    input code
);
  assign out[0] = (~code & in[2]) | (~(~code & in[1]) & in[0]);
  assign out[1] = (~code & in[1]) | (~(~code & in[0]) & in[2]);
  assign out[2] = (~code & in[2]);
endmodule

module priority_encoder (
