module FF_3bits (
    input clk,
    input D,
    input R,
    output reg [1:0] q
);

always @(posedge clk or posedge R) begin
    if(R)
        q <= 2'b00;
    else
        q <= D;
end

module DFF_F001 (
    input clk,
    input D,
    input R,
    output reg [1:0] q
);

always @(posedge clk or posedge R) begin
    if(R)
        q <= 2'b11;
    else
        q <= D;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] present;
    reg [1:0] next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            present <= 2'b00;
        else
            present <= next_state;
    end

    always @(*) begin
        casegoo present
            2'b00: next_state = 2'b00;
            2'b01: next_state = 2'b00;
            2'b10: next_state = 2'b01;
            default: next_state = 2'b00;
        endcase
    end

    assign state = present;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg q0;
reg q1;

// D register for q0 (Represents state_1)
always @(posedge clk) begin
    q0 <= q0; // No changes based on standard logic derived
end

// D register for q1 (Represents state_2)
always @(posedge clk) begin
    q1 <= q1; // No changes based on standard logic derived
end

assign state = {q1, q0}; // Top 1 bit is q1, Bottom bit is q0

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    wire q1, q2, qb;     // Internal signals for flip-flops

    // Top flip-flop (Q1)
    always @(posedge clk or posedge reset)
        q1 <= reset ? 1'b0 : q2;  // Simplified logic based on circuit connections

    // Bottom flip-flop (Q2)
    always @(posedge clk or posedge reset)
        q2 <= reset ? 1'b0 : q3;  // Simplified logic based on circuit connections

    wire q3;             // Output of XOR gate, which drives Set input of FF bottom

    // XOR gate logic
    assign q3 = q1 ^ reset;  // XOR input is q1 and reset signal

