module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    wire a, b, c, d, e; // Intermediate signals

    // First stage of logic (rows 0 to 5)
    a = data_in[0];
    b = data_in[1];
    c = data_in[2];
    d = data_in[3];
    e = data_in[4];

    // XOR gate 1 (row 0)
    data_out[0] = a ^ ~a;

    // XOR gate 2 (row 1)
    data_out[1] = ~b ^ b;

    // XOR gate 3 (row 2)
    data_out[2] = c ^ c;

    // XOR gate 4 (row 3)
    data_out[3] = (d ^ (e ^ ~e)) ^ (e ^ ~e);

    // XOR gate 5 (row 4)
    data_out[4] = ~(e ^ e);

    // XOR gate 6 (row 5)
    data_out[5] = (d ^ (e ^ ~e)) ^ (e ^ ~e);

    // Second stage of logic (rows 6 to 7)
    // These are similar to rows 6 and 7 in the diagram, but are not unique in their function.

    // XOR gate 7 (row 6)
    data_out[6] = a ^ b ^ c ^ d ^ e;

    // XOR gate 8 (row 7)
    data_out[7] = b ^ c ^ d ^ e ^ a;

endmodule

