module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    // 1-bit comparator logic for bits a[3:0] and b[3:0]
    // This module represents the internal logic for comparing two 4-bit numbers.

    wire m0, m1, m2, m3;       // Minorities: (a<3>=b<3>) & ((a<3)==b<3>)
    wire > ;                    // Greater than comparison
    wire < ;                    // Less than comparison

    // Comparator logic for most significant bits to least significant bit.
    // a and b are masked to isolate each bit
    assign m0 = ~((~a[3]) | (~b[3]) | (a[3] & b[3]));
    assign m1 = ~((~a[2]) | (~b[2]) | (a[2] & b[2]));
    assign m2 = ~((~a[1]) | (~b[1]) | (a[1] & b[1]));
    assign m3 = ~((~a[0]) | (~b[0]) | (a[0] & b[0]));

    // Use a 32-bit full adder to compare the two numbers
    // This assumes the full subtractor logic is applied
    wire og, o1, o2, o3, o4, og1, og2, og3, og4;

    assign og = (a[3] & b[3]) ^ ~(a[2] & b[2]) ^ ~(a[1] & b[1]) ^ ~(a[0] & b[0]);
    assign o1 = ~(a[2] & b[2]) ^ ~(a[1] & b[1]) ^ ~(a[0] & b[0]);
    assign o2 = ~(a[1] & b[1]) ^ ~(a[0] & b[0]);
    assign o3 = ~(a[0] & b[0]);
    assign o4 = 0;           // 4th operand is always 0 for a 4-bit subtraction

    // Perform 4-bit subtraction
    // a - b
    assign gt = (a > b);
    assign lt = (a < b);
    assign eq = (a == b);

endmodule

