module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire w0, w1, w2, w3;
    wire w4, w5, w6, w7;
    wire w8, w9, w10, w11;

    // Slices of a
    assign w0 = a[0];
    assign w1 = a[1];
    assign w2 = a[2];
    assign w3 = a[3];

    // Slices of b
    assign w4 = b[0];
    assign w5 = b[1];
    assign w6 = b[2];
    assign w7 = b[3];

    // Greater Than Logic
    assign gt = ((w3 & ~w7) | ((w7 & ~w6) & w3) | ((w7 & w6) & (w4 & ~w5)) | ((w7 & w6) & (~w5 & w4)) | ((w7 & w6) & (~w5 & w4)));

    // Equality Logic
    assign eq = (w3 ^ w7) | (w2 ^ ~w6) | ((w1 & w5) | (~w1 & ~w5));

    // Less Than Logic
    assign lt = (w7 & w6 & w5 & w4) | (~w7 & w6 & ~w5 & ~w4);

endmodule

