    wire m0, m1, m2, m3; // Intermediate outputs from AND gates

    // Multiplexed outputs
    assign y0 = a[0];
    assign y1 = a[1];
    assign y2 = a[2];
    assign y3 = a[3];

    // First layer of AND gates
    assign w0 = a[0] & b[3];
    assign w1 = a[1] & b[3];
    assign w2 = a[2] & b[1];
    assign w3 = a[3] & b[0];

    // Second layer of AND gates
    assign m0 = b[3] & b[2];
    assign m1 = b[3] & b[1];
    assign m2 = b[3] & b[0];

    // NO gate logic for comparison
    assign eq = (~((y0==y1) && (y1==y2) && (y2==y3)));
    assign lt = (~y0) || (~y1);
    assign gt = y0 || y1;

    output reg gt_reg;
    output reg eq_reg;
    output reg lt_reg;

