  logic D;
  logic E;

  // Inputs/Outputs for FFs
  assign D = state;
  assign E = !state;

  // Instantiate DFFs
  DFF_PPD_MV1P_1 DFF0 (
    .Q(s_DFFE_PP0P[0]),
    .D(D),
    .E(E),
    .C(clk),
    .R (!areset)
  );

