    .Q(s_DFFE_PP0P[1]),
    .D(s_DFFE_PP0P[0]),
    .E(!s_DFFE_PP0P[1]),
    .C(clk),
    .R (0)
  );

  // Logic for state edges
  logic [1:0] tmp_state;

  // D latch implementation for State[0]
  logic state_latch_d0;
  logic_eula G0 (
    .e_pulse(state[0]),
    .e_pulse_not(!state[0]),
    .e_fence(!areset),
    .e_fence_not(areset),
    .out(state_latch_d0),
    .out_not(!state_latch_d0)
  );

  logic_eula G1 (
    .e_pulse(state[1]),
    .e_pulse_not(!state[1]),
    .e_fence(!areset),
    .e_fence_not(areset),
    .out(D),
    .out_not(!D)
  );

  logic_eula G2 (
    .e_pulse(state[1]),
    .e_pulse_not(!state[1]),
    .e_fence(!areset),
    .e_fence_not(areset),
    .out(E),
    .out_not(!E)
  );

  // Combining edge conditions
  logic_eula G3 (
    .e_pulse(state[0]),
    .e_pulse_not(!state[0]),
    .e_fence(!areset),
    .e_fence_not(areset),
    .out(tmp_state[1]),
    .out_not(!tmp_state[1])
  );

