module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  reg [1:0] temp_state;
  wire nbt, sample, sample_or;
  wire async_reset;

  // First D-FF and its associated logic
  always @(posedge clk) begin
    if (areset)
      temp_state <= 2'b00;
    else if (train_valid && !train_taken)
     temp_state <= temp_state + 1;
    else
      temp_state <= temp_state; // Wait
  end

  // Logic to generate async_reset
  assign async_reset = ~nbt;

  // Logic to generate nbt
  assign nbt = !(train_valid & !train_taken & (temp_state == 2'b11));

  // Logic to generate sample
  assign sample = (!areset && nbt) ? 0 : (temp_state == 2'b10);

  // Logic to generate sample_or
  assign sample_or = !(train_valid & !train_taken);

  // Final output assignment
  assign state = sample;

endmodule

