    wire w11 = (~e & (~w7 & (~d & ~c & ~w3)));
    wire w12 = (~c & (~e & (~b & ~d & ~w2)));
    wire w13 = (~d & (~w5 & (~c & ~w6)));
    wire w14 = (~b & (~w9 & (~w1 & (~a & e))));

