module TopModule (
  input  [3:0] in,
  output [3:0] out_both,
  output [3:0] out_any,
  output [3:0] out_different
);

always @(*) begin
    // out_different
    integer i;
    for (i = 0; i <= 3; i = i + 1) begin
        case (i)
            0: out_different[0] = in[0] ^ (in[1] | in[2]);
            1: out_different[1] = in[1] ^ (in[0] | in[2]);
            2: out_different[2] = in[2] ^ (in[0] | in[1]);
            3: out_different[3] = in[3] ^ (in[0] | in[1] | in[2]);
            default: out_different[i] = 0;
        endcase
    end

    // out_both
    case ({in[0], in[1], in[2], in[3]})
        4'b0000:      // No bits set
            out_both[0] = 5;
            out_both[1] = 6;
            out_both[2] = 7;
            out_both[3] = 15;
        4'b0001:      // Bit 0 set
            out_both[0] = 7;
            out_both[1] = 6;
            out_both[2] = 5;
            out_both[3] = 11;
        4'b0010:      // Bit 1 set
            out_both[0] = 5;
            out_both[1] = 7;
            out_both[2] = 6;
            out_both[3] = 7;
        4'b0011:      // Bits 0 and 1 set
            out_both[0] = 4;
            out_both[1] = 5;
            out_both[2] = 6;
            out_both[3] = 7;
        default:
            out_both[3] = 7;
    endcase

    // out_any
    integer i;
    for (i = 0; i <= 3; i = i + 1) begin
        sum[i] = in[i];
        for (j = i + 1; j <= 3; j = j + 1) begin
                bit[i] = in[i] ^ (in[j] | (in[j + 1] ? in[j] : in[i] ? in[j] : 1));
                sum = sum ^ bit;
        end
    end
    for (i = 0; i <= 3; i = i + 1) begin
        out_any[i] = sum[i];
    end
end

parameter bit[2] = 2;
always @(*) begin
    int sum[2] = 1;
    assign sum[0] = 4'b0000;
    sum = 0;
    for (i = 0; i <= 3; i = i + 1) begin
        bit = 0;
        bit = 0;
        bit[i] = in[i] ^ (in[j] | (in[j + 1] ? in[j] : in[i] ? in[j] : 1));
        sum = sum ^ bit;
    end

    // out_any
    for (i = 0; i <= 3; i = i + 1) begin
        out_any[i] = sum[i];
    end
end
endmodule

