    shifted_invertor: invertor(.x(flipped_clk), .y(clk_div));

    // Clock Divider
    clk_divider: clock_divider
      (.clk(clk), 
       .rst_n(flipped_rst_n),
       .clk_out(clk_div));

    // End of Module
endmodule

