module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

   wire d0, d1, d2, d3;
   wire qn0, qn1;

   assign qn0 = (~d0) & data_in;
   assign d0  = (qn0 &  qn0);
   assign qn0 = (d0 & qn1) & data_in;

   assign d2  = (~qn0 & data_in);
   assign d1  = (d2 & ~qn1);
   assign qn1 = (d1 & data_in);

   assign d2  = (qn1 & ~qn0);
   assign d1  = (d2 & data_in);
   assign sequence_detected = d1;

   flip_flop f1(
       .clk(clk),
       .rst(!rst_n),
       .d(data_in),
       .q(d0));

   flip_flop f2(
       .clk(clk),
       .rst(!rst_n),
       .d(qn0),
       .q(qn1));

   flip_flop f3(
       .clk(clk),
       .rst(!rst_n),
       .d(d0),
       .q(d1));

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

   reg q0, q1, q2;

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         q0 <= 1'b0;
         q1 <= 1'b0;
         q2 <= 1'b0;
      end
      else begin
         q0 <= data_in;
         q1 <= data_in & q0;
         q2 <= data_in & q0 & q1;
      end
   end

   assign sequence_detected = q2;

endmodule

module sequence_detector(
// Detect the sequence "10101" on the input 'data'. The output 'sequence_detected' is 0 for one clock cycle after the sequence is detected.
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

wire s, p, d, q_0, q_1, clock;
assign clock = clk;

// Shift register part (S) -> state 0
// s = sequence detected flag
// q_0 = "wait 1"
// q_1 = "wait 0"
// d = "check for 0"
assign s = sequence_detected;
assign p = data_in & ~clock;
assign d = ~p;
assign q_0 = data_in & ~s;
assign q_1 = s & ~p;

// State machine
always_FF (@ (posedge clk) or (negedge rst_n))
begin
    if(!rst_n)
        s <= 0;
    else if(p)
        d <= d;
    else
    begin
        if(d)
            q_0 <= q_1;
        else if(q_1)
            s <= ~s;
    end
end

// Assigning back to outputs
assign sequence_detected = s;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    wire q0, q1, q2, q3;
    wire not_rst, not_clk;
    wire input1, input2, and_output;

    // NC_TIMER1 Constitution
    always @(posedge q0)
        not_rst = rst_n;

    always @(posedge not_rst)
        clk = clk;

    always @(posedge clk)
        q0 = data_in;

    // Input logic
    and_output = q0 && data_in;

    always @(posedge clk)
        q1 = and_output;

    // PID_K1_Combination
    wire pid_a;
    wire pid_b;

    assign pid_a = q0 && q1;
    assign pid_b = q0 && not_rst;

    always @(posedge clk)
        q2 = q1; // Data_in

    // Output Logic
    wire or_gate_output;
    wire and_gate_output;
    wire not_seq_output;

    assign or_gate_output = q2 | q1;
    assign and_gate_output = q2 && q1;
    assign not_seq_output = not_seq_output; // Identity function

    // PID_K2_Combination
    wire pid_k2_clk;
    wire pid_k2_data;

    assign pid_k2_clk = q1;
    assign pid_k2_data = q0;

    always @(posedge clk)
        q3 = or_gate_output;

    // Final Output
    assign sequence_detected = q3;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     // Define state variables
     wire sdff_pn0_q;qd
     wire sdff_pn1_q;qd

     assign sdff_pn0_q = (sdfp_pn0_q & !data_in) ^ (sdfp_pn0_q & data_in);
     assign sdff_pn1_q = (sdfp_pn1_q & sdf_pn0_q) ^ sdf_pn1_q;

     // Detect sequence
     assign sequence_detected = sdf_pn1_q;

     // State assignment
     wire sdff_pn0_q;qd = (!data_in & sdf_pn0_q) & (~sdf_pn1_q);
     wire sdff_pn1_q;qd = (!data_in & sdf_pn1_q) | (!sdff_pn0_q & sdff_pn1_q);

endmodule
